/* Original vector scene: no remote assets or external requests. */
(function(root){
const icons={city:'M3 20V9l6-4v15m0-12 6-5v17m0-10 6-3v13M2 21h20',cards:'m5 5 11-2 4 15-11 2zM4 9l-2 1 4 12 10-3',bag:'M5 7h14l2 14H3L5 7Zm3 0V5a4 4 0 0 1 8 0v2',book:'M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3zM12 6v16',clock:'M12 8v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',gear:'M9 3h6l1 4 4 2v6l-4 2-1 4H9l-1-4-4-2V9l4-2zM15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',coin:'M20 12a8 8 0 1 1-16 0 8 8 0 0 1 16 0M14 7h-4v10h4M8 10h8m-8 4h8',arrow:'m9 5 7 7-7 7',wood:'m4 16 10-10 6 6-10 10zM4 16l6 6m-3-9 6 6',blueprint:'M4 3h16v18H4zM7 8h10M7 12h6M7 16h10'};
function icon(name){return `<svg class="ico" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.city}"/></svg>`}
function building(x,y,w,h,height,roof='#b96358'){return `<g transform="translate(${x},${y})"><path d="M0 0 ${w} ${w/2} ${w-h} ${(w+h)/2} ${-h} ${h/2}Z" fill="#79998d" opacity=".3" transform="translate(10 8)"/><path d="M${-h} ${h/2-height} 0 ${-height} 0 0 ${-h} ${h/2}Z" fill="#c8bba0"/><path d="M0 ${-height} ${w} ${w/2-height} ${w} ${w/2} 0 0Z" fill="#eee0bb"/><path d="M${-h} ${h/2-height} 0 ${-height} ${w} ${w/2-height} ${w-h} ${(w+h)/2-height}Z" fill="${roof}"/>${Array.from({length:Math.max(1,Math.floor(height/18))},(_,i)=>`<path d="M8 ${-height+12+i*17} 16 ${-height+16+i*17}v7l-8-4zm20 10 8 4v7l-8-4z" fill="#587779"/>`).join('')}<path d="M${-h+5} ${h/2-height+12}v${Math.max(4,height-19)}" stroke="#a89c84" stroke-width="3"/></g>`}
function tree(x,y,k=1){return `<g transform="translate(${x} ${y}) scale(${k})"><ellipse cy="5" rx="16" ry="7" fill="#578d7640"/><path d="M0 0v-22" stroke="#8e8871" stroke-width="5"/><path d="M-17-20 0-56 18-20z" fill="#6a9f82"/><path d="M0-56v36h18Z" fill="#4e866f"/></g>`}
function map(s,{interactive=true}={}){const c=s?.city||{districts:[],blueprints:['trend']};const plots=[{id:'trend',x:260,y:300,w:160,h:125,roof:'#b66d60',label:'追光港'},{id:'value',x:630,y:420,w:160,h:125,roof:'#6f8e9c',label:'星河街'},{id:'defense',x:370,y:640,w:160,h:125,roof:'#808969',label:'月湾园'}];return `<svg class="world" viewBox="0 0 900 950" role="img" aria-label="海岛策略城市，可点击三个地块建设"><defs><pattern id="sea" width="65" height="48" patternUnits="userSpaceOnUse"><path d="M12 20q10-5 20 0m15 20q7-4 14 0" fill="none" stroke="#abd4cf" opacity=".45"/></pattern><pattern id="road" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M0 20h40" stroke="#faf1d1" stroke-width="2" stroke-dasharray="8 8"/></pattern><filter id="shadow"><feDropShadow dx="0" dy="6" stdDeviation="4" flood-color="#315c52" flood-opacity=".2"/></filter></defs><rect width="900" height="950" fill="#83bbb7"/><rect class="sea" x="-70" y="-48" width="1040" height="1050" fill="url(#sea)"/><path d="M40 235 365 70 855 325 840 655 518 847 65 610Z" fill="#62998a"/><path d="M40 218 365 53 855 308 840 638 518 830 65 593Z" fill="#d8d4b3"/><path d="M63 222 366 72 833 316 819 625 518 808 86 581Z" fill="#aebc91"/><path d="m365 90-230 490 385 200M100 250l690 355M650 235 420 710" fill="none" stroke="#e4dcc0" stroke-width="48" stroke-linejoin="round"/><path d="m365 90-230 490 385 200M100 250l690 355M650 235 420 710" fill="none" stroke="#a8aba1" stroke-width="32" stroke-linejoin="round"/><path d="m365 90-230 490 385 200M100 250l690 355M650 235 420 710" fill="none" stroke="#ece6ce" stroke-width="1.7" stroke-dasharray="9 12"/>${building(410,180,38,42,48,'#627f8c')}${building(485,215,34,40,38,'#bb8465')}${building(715,575,40,35,26,'#ba6f58')}${building(185,615,35,38,32,'#777d9e')}${[[130,270],[185,205],[255,160],[760,365],[765,420],[520,720],[580,740],[620,685],[115,525],[680,290]].map(([x,y])=>tree(x,y,.9)).join('')}<g class="car"><path d="m432 409 19 10 13-7-19-10z" fill="#fbecd0"/><path d="m432 409v6l19 10v-6z" fill="#b45d4c"/><path d="m451 419 13-7v6l-13 7z" fill="#7f4541"/></g>${plots.map(p=>{const d=c.districts.find(d=>d.id===p.id),locked=!c.blueprints.includes(p.id),hei=d?30+d.development*.85:0;return `<g class="plot ${d?'constructed':'vacant'} ${locked?'locked':''}" ${interactive?`role="button" tabindex="0" data-do="district" data-id="${p.id}" aria-label="${p.label} ${d?'进入区域':'建造区域'}"`:''} transform="translate(${p.x} ${p.y})"><path class="plotglow" d="m-100 0 90-45 150 75-90 45z" fill="${d?'#c6c4a0':'#e5dbb7'}" stroke="${d?'#d9d3b0':'#fcf4d7'}" stroke-width="3" stroke-dasharray="${d?'0':'8 6'}"/>${d?building(-5,8,55,50,hei,p.roof)+building(65,39,35,36,Math.max(20,hei-20),p.roof):`<path d="M-15-15v35m-18-17 36 18" stroke="#9a9c7b" stroke-width="8" stroke-linecap="round"/>`}<g transform="translate(12 ${d?90:65})" filter="url(#shadow)"><rect x="-65" y="-18" width="130" height="37" rx="17" fill="${locked?'#747f72':'#f3eedb'}"/><text text-anchor="middle" y="5" fill="${locked?'#e4e3d4':'#465e55'}" font-size="17" font-weight="650">${locked?'未发现 · '+p.label:p.label+(d?'':' · 建造')}</text></g>${d?`<text x="12" y="125" text-anchor="middle" fill="#435c50" font-size="13">建设 ${d.development}% · 稳定 ${d.stability}%</text>`:''}</g>`}).join('')}<path d="M780 650 855 689M774 665l75 40" stroke="#987c61" stroke-width="8"/><g class="boat" transform="translate(760 790)"><path d="m-28 0 30 16 38-20-30-14z" fill="#f6ecd1"/><path d="m-28 0 30 16v10l-25-13z" fill="#ba715b"/><path d="M2 16 40-4l-5 15L2 26Z" fill="#986250"/><path d="M3 7v-48l-25 35z" fill="#fff9e4"/></g><g class="cloud" fill="#f4f1df" opacity=".6"><ellipse cx="165" cy="70" rx="100" ry="25"/><ellipse cx="125" cy="65" rx="40" ry="35"/><ellipse cx="208" cy="55" rx="45" ry="35"/></g><g class="cloud cloud2" fill="#f4f1df" opacity=".45"><ellipse cx="760" cy="160" rx="110" ry="22"/><ellipse cx="720" cy="147" rx="45" ry="30"/></g><g class="gulls" fill="none" stroke="#f6f0d8" stroke-width="3"><path d="M70 740q8-9 16 0 8-9 16 0M110 770q8-9 16 0 8-9 16 0"/></g></svg>`;}
root.CityArt={map,icon};
})(window);
